UPDATE PA_BASIC_DATA SET END_DATE = CASE WHEN END_DATE < TO_DATE(#START_DATE:VARCHAR#,'YYYY-MM-DD')-1 THEN END_DATE ELSE TO_DATE(#START_DATE:VARCHAR#,'YYYY-MM-DD')-1 END, UPDATE_DATE = SYSDATE, UPDATED_BY = #UPDATED_BY:VARCHAR#, ACTIVITY = 0 WHERE ROWID IN (SELECT ROWID FROM (SELECT ROWID, ROW_NUMBER() OVER(ORDER BY START_DATE DESC) RN FROM PA_BASIC_DATA WHERE PARAM_NO = #PARAM_NO:NUMERIC# AND PERSON_ID = #PERSON_ID:VARCHAR#
BASIC_DATA_NO <> #NOT_BASIC_DATA_NO:VARCHAR#
) WHERE RN = 1)
